2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|42px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="What You Get From the Assessment" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#ffffff" text_font_size="16px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#ffffff" header_2_font_size="46px" header_2_font_size_tablet="46px" header_2_font_size_phone="28px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-0.035em"]<h2 class="white-heading">What You Get From the <span class="accent">Assessment</span></h2>[/et_pb_text][et_pb_text admin_label="Section introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="rgba(255,255,255,.72)" text_font_size="17px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Clear findings, prioritized opportunities, and a practical path to unlock additional capacity with the system you already have.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row admin_label="Three assessment deliverables" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="1_3,1_3,1_3" module_class="anca-row anca-stack-tablet" width="calc(100% - 40px)" max_width="1140px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="on" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="1. Clarity on Current Capacity Constraints" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="1_3" module_class="anca-deliverable" custom_padding="32px|28px|32px|28px|false|false" background_color="#ffffff"][et_pb_text admin_label="1. Clarity on Current Capacity Constraints" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_3_font="Arial|900|||||||" header_3_text_color="#111114" header_3_font_size="21px" header_3_font_size_tablet="21px" header_3_font_size_phone="21px" header_3_font_size_last_edited="on|phone" header_3_line_height="1.08em" header_3_letter_spacing="0px"]<h3>1. Clarity on Current Capacity Constraints</h3>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Gain a clear understanding of where capacity is being constrained across your operation. Through a structured review of your value stream, production processes, resources, and workflows, we identify:</p>[/et_pb_text][et_pb_text admin_label="Deliverable checklist" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#333333" text_font_size="13px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul>
              <li>Primary and secondary bottlenecks</li>
              <li>Areas where flow is being disrupted</li>
              <li>Capacity limitations across labor, equipment, materials, and processes</li>
              <li>Constraints that are limiting throughput, responsiveness, and growth</li>
            </ul>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p class="small-copy">The result is a clear picture of what is currently preventing your operation from producing more with the resources you already have.</p>[/et_pb_text][/et_pb_column][et_pb_column admin_label="2. Opportunities to Increase Capacity" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="1_3" module_class="anca-deliverable" custom_padding="32px|28px|32px|28px|false|false" background_color="#ffffff"][et_pb_text admin_label="2. Opportunities to Increase Capacity" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_3_font="Arial|900|||||||" header_3_text_color="#111114" header_3_font_size="21px" header_3_font_size_tablet="21px" header_3_font_size_phone="21px" header_3_font_size_last_edited="on|phone" header_3_line_height="1.08em" header_3_letter_spacing="0px"]<h3>2. Opportunities to Increase Capacity</h3>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Most manufacturers have more capacity than they realize. Hidden within everyday operations are inefficiencies that consume resources, create delays, and limit throughput. The assessment uncovers opportunities to improve operational performance and reclaim lost capacity without significant capital investment.</p>[/et_pb_text][et_pb_text admin_label="Deliverable checklist" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#333333" text_font_size="13px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul>
              <li>Eliminate waste and non-value-added activities</li>
              <li>Improve workflow and process efficiency</li>
              <li>Reduce delays, waiting, and rework</li>
              <li>Improve utilization of labor and equipment</li>
              <li>Increase throughput using existing resources</li>
            </ul>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p class="small-copy">The goal is simple: create additional capacity that can be used to absorb growth, improve service levels, and increase profitability.</p>[/et_pb_text][/et_pb_column][et_pb_column admin_label="3. A Roadmap to Achieve Growth Targets" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="1_3" module_class="anca-deliverable" custom_padding="32px|28px|32px|28px|false|false" background_color="#ffffff"][et_pb_text admin_label="3. A Roadmap to Achieve Growth Targets" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_3_font="Arial|900|||||||" header_3_text_color="#111114" header_3_font_size="21px" header_3_font_size_tablet="21px" header_3_font_size_phone="21px" header_3_font_size_last_edited="on|phone" header_3_line_height="1.08em" header_3_letter_spacing="0px"]<h3>3. A Roadmap to Achieve Growth Targets</h3>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Knowing your constraints is only valuable if you have a plan to address them. Based on the assessment findings, you receive a practical roadmap outlining the changes required to support your growth objectives.</p>[/et_pb_text][et_pb_text admin_label="Deliverable checklist" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#333333" text_font_size="13px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul>
              <li>Priority improvement initiatives</li>
              <li>Recommended actions to elevate identified constraints</li>
              <li>Capacity improvement opportunities ranked by impact</li>
              <li>Short-, medium-, and long-term recommendations</li>
              <li>Key milestones needed to achieve growth targets</li>
            </ul>[/et_pb_text][et_pb_text admin_label="Deliverable description" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="15px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p class="small-copy">You leave with a clear understanding of what must change, where to focus first, and how to build the operational capacity required to support future demand.</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section admin_label="08 | Bonus 1 - Benchmark report" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" fb_built="1" module_class="anca-section" background_color="#f7f7f7" custom_padding="76px|0px|76px|0px|false|false" custom_padding_phone="58px|0px|58px|0px|false|false" custom_padding_last_edited="on|phone"][et_pb_row admin_label="Section heading and introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="790px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|42px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Bonus #1: Manufacturing Performance Benchmark Report" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#111114" header_2_font_size="56px" header_2_font_size_tablet="46px" header_2_font_size_phone="30px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-0.05em"]<h2 class="eyebrow"><span class="bonus-prefix">Bonus #1:</span> <span class="bonus-rest">Manufacturing Performance Benchmark Report</span></h2>[/et_pb_text][et_pb_text admin_label="Section introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="17px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>The assessment is focused on one question: what is currently constraining your ability to produce more output with your existing system?</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row admin_label="Bonus report" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="760px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="Bonus report details" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="anca-benchmark" custom_padding="42px|40px|42px|40px|false|false" background_color="#ffffff" custom_padding_phone="28px|24px|28px|24px|false|false" custom_padding_last_edited="on|phone"][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>In addition to your Constraint Capacity Assessment&trade;, you'll receive a comparative analysis of key performance indicators against industry peers, including:</p>[/et_pb_text][et_pb_text admin_label="Benchmark metrics" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|800|||||||" text_text_color="#111114" text_font_size="20px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul class="benchmark-list">
              <li>Revenue Growth</li>
              <li>EBITDA Performance</li>
              <li>Inventory Turns</li>
              <li>Efficiency</li>
              <li>Gross Margins</li>
              <li>And many others</li>
            </ul>[/et_pb_text][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Because improvement opportunities are easier to identify when you understand how your operation compares to others in the market.</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section admin_label="09 | Bonus 2 - Cost intelligence" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" fb_built="1" module_class="anca-section anca-soft" background_color="#ffffff" custom_padding="76px|0px|76px|0px|false|false" custom_padding_phone="58px|0px|58px|0px|false|false" custom_padding_last_edited="on|phone"][et_pb_row admin_label="Section heading and introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="790px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|42px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Bonus #2: The Cost Intelligence Assessment" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#111114" header_2_font_size="56px" header_2_font_size_tablet="46px" header_2_font_size_phone="30px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-0.05em"]<h2 class="eyebrow"><span class="bonus-prefix">Bonus #2:</span> <span class="bonus-rest">The Cost Intelligence Assessment</span></h2>[/et_pb_text][et_pb_text admin_label="Section introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="17px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>A free, custom diagnostic built from your own numbers &mdash; not a template, not a guess.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row admin_label="Bonus report" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="760px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="Bonus report details" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="anca-benchmark" custom_padding="42px|40px|42px|40px|false|false" background_color="#ffffff" custom_padding_phone="28px|24px|28px|24px|false|false" custom_padding_last_edited="on|phone"][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>The assessment is built from your actual accounts payable data &mdash; your vendors, your locations, your transactions. We take it apart line by line and hand you back a live map of where your indirect spend is actually going, and where it&rsquo;s quietly leaking.</p>[/et_pb_text][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|800|||||||" text_text_color="#111114" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p class="bonus-emphasis">No sample data. No hypotheticals. Yours.</p>[/et_pb_text][et_pb_text admin_label="What You Get" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="14px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_3_font="Arial|900|||||||" header_3_text_color="#111114" header_3_font_size="22px" header_3_font_size_tablet="22px" header_3_font_size_phone="22px" header_3_font_size_last_edited="on|phone" header_3_line_height="1.08em" header_3_letter_spacing="-0.02em"]<h3 class="bonus-subhead">What You Get</h3>[/et_pb_text][et_pb_text admin_label="Cost intelligence findings" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.75em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul class="benchmark-list benchmark-list--detail">
              <li><strong>Your real spend breakdown.</strong> Every dollar of indirect cost, sorted by category and location: production supplies, logistics, facilities, utilities, insurance, and beyond. See exactly what you&rsquo;re spending, where, and with whom.</li>
              <li><strong>Your vendor concentration map:</strong> Most manufacturers are stunned to find they&rsquo;re running 600+ suppliers in categories where 15 would do the job better. We&rsquo;ll show you your number, and how this affects how your team is actually spending its time &mdash; managing instead of building.</li>
              <li><strong>Your opportunity matrix:</strong> Not a list of &ldquo;ideas.&rdquo; A ranked map plotting impact against effort, so you know precisely where to start, what to leave alone, and what&rsquo;s worth a second look.</li>
              <li><strong>Your addressable vs. non-addressable split:</strong> We separate what can realistically move (packaging, transportation, operating supplies) from what can&rsquo;t (leases, taxes, labor) so you&rsquo;re not chasing savings that were never on the table.</li>
            </ul>[/et_pb_text][et_pb_text admin_label="Why Participate?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="14px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_3_font="Arial|900|||||||" header_3_text_color="#111114" header_3_font_size="22px" header_3_font_size_tablet="22px" header_3_font_size_phone="22px" header_3_font_size_last_edited="on|phone" header_3_line_height="1.08em" header_3_letter_spacing="-0.02em"]<h3 class="bonus-subhead">Why Participate?</h3>[/et_pb_text][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|20px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Many organizations have opportunities hidden within their existing supplier relationships that are difficult to identify without specialized market intelligence. This complimentary assessment provides an objective view of your spending and helps determine whether additional savings opportunities may exist.</p>[/et_pb_text][et_pb_text admin_label="Bonus explanation" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="18px" text_line_height="1.8em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>There is no cost, no obligation, and no commitment to move forward. The assessment simply provides actionable insight so you can make informed decisions about your organization&rsquo;s purchasing strategy.</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section admin_label="10 | Why visibility matters now" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" fb_built="1" module_class="anca-section anca-soft" background_color="#ffffff" custom_padding="76px|0px|76px|0px|false|false" custom_padding_phone="58px|0px|58px|0px|false|false" custom_padding_last_edited="on|phone"][et_pb_row admin_label="Section heading and introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="790px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|42px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Why Constraint Visibility Matters Now" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#111114" header_2_font_size="46px" header_2_font_size_tablet="46px" header_2_font_size_phone="28px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-0.035em"]<h2>Why Constraint Visibility <span class="accent">Matters Now</span></h2>[/et_pb_text][et_pb_text admin_label="Section introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="17px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Most manufacturing systems do not fail from lack of demand. They fail from misidentified constraints, locally optimized improvements, and hidden capacity loss.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row admin_label="Leadership quote" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="900px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Constraint visibility quote" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|900|||||||" text_text_color="#ffffff" text_font_size="24px" text_line_height="1.22em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="42px|42px|42px|42px|false|false" module_class="anca-quote" background_color="#070707" text_letter_spacing="-.025em" text_font_size_phone="18px" text_font_size_last_edited="on|phone" custom_padding_phone="32px|24px|32px|24px|false|false" custom_padding_last_edited="on|phone"]
          <p>Growth gets approved based on sales confidence, but executed against operational uncertainty. This assessment closes that gap.</p>
