n="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" min_height="auto"][/et_pb_image][/et_pb_column][et_pb_column admin_label="George Smith" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="1_3" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_image admin_label="George Smith" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" src="https://alphanovaconsulting.com/wp-content/uploads/2026/06/2.-George-Smith-1.jpg" alt="George Smith" title_text="George Smith" align="center" show_in_lightbox="off" force_fullwidth="on" module_class="anca-testimonial" background_color="#0b0b0d" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" min_height="auto"][/et_pb_image][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section admin_label="13 | Frequently asked questions" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" fb_built="1" module_class="anca-section" background_color="#f7f7f7" custom_padding="76px|0px|76px|0px|false|false" custom_padding_phone="58px|0px|58px|0px|false|false" custom_padding_last_edited="on|phone" module_id="faq"][et_pb_row admin_label="Section heading and introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="790px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|42px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Frequently Asked Questions" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#111114" text_font_size="16px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|14px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#111114" header_2_font_size="46px" header_2_font_size_tablet="46px" header_2_font_size_phone="28px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-0.035em"]<h2>Frequently Asked <span class="accent">Questions</span></h2>[/et_pb_text][et_pb_text admin_label="Section introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#6d6d6d" text_font_size="17px" text_line_height="1.55em" text_orientation="center" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Common questions manufacturing leaders ask before requesting a Capacity Constraint Assessment.</p>[/et_pb_text][/et_pb_column][/et_pb_row][et_pb_row admin_label="Eleven editable FAQ toggles" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="4_4" module_class="anca-row" width="calc(100% - 40px)" max_width="920px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="Content" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="4_4" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_toggle admin_label="How is this different from a Lean assessment?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="How is this different from a Lean assessment?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>Most Lean assessments evaluate a broad range of operational practices and improvement opportunities. The Capacity Constraint Assessment focuses on one specific question: what is currently limiting our ability to produce more output and support future growth? Rather than evaluating every aspect of the business, we focus on identifying the constraints, inefficiencies, and capacity limitations that are restricting throughput and growth.</p>[/et_pb_toggle][et_pb_toggle admin_label="We already know our bottleneck. Why do we need an assessment?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="We already know our bottleneck. Why do we need an assessment?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>Many manufacturers believe they know their bottleneck. In reality, what appears to be the constraint is often a symptom of a deeper issue elsewhere in the system. Organizations may invest in equipment, add labor, or expand facilities only to discover the true constraint was in scheduling, material flow, quality, changeovers, planning, or management systems. This assessment helps ensure resources are invested where they will create the greatest impact.</p>[/et_pb_toggle][et_pb_toggle admin_label="Will this disrupt day-to-day operations?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="Will this disrupt day-to-day operations?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>No. The assessment is designed to minimize disruption while gathering the information necessary to understand how work flows through the operation. Most of the work involves observation, data review, leadership discussions, and targeted process analysis. Your team continues running the business while we evaluate how the system performs.</p>[/et_pb_toggle][et_pb_toggle admin_label="How long does the assessment take?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="How long does the assessment take?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>Most assessments are completed within 2–4 weeks depending on facility size, complexity, and data availability. At the conclusion, findings, recommendations, and the Ramp-Up Plan are presented to your leadership team.</p>[/et_pb_toggle][et_pb_toggle admin_label="Do we need accurate capacity data to participate?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="Do we need accurate capacity data to participate?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>No. Many manufacturers struggle with incomplete or inconsistent capacity information. Part of the assessment process is validating assumptions and developing a realistic understanding of operational capacity. We work with the data available and supplement it through observation, interviews, and analysis.</p>[/et_pb_toggle][et_pb_toggle admin_label="What types of manufacturers benefit most from this assessment?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="What types of manufacturers benefit most from this assessment?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>The Capacity Constraint Assessment is designed for manufacturers that are experiencing growth or preparing for growth, running near capacity, missing delivery commitments, increasing overtime without seeing corresponding output gains, considering capital investments or expansion, or unsure whether current operations can support future demand. It is particularly valuable for organizations that feel operationally stretched but lack clarity on what is driving the pressure.</p>[/et_pb_toggle][et_pb_toggle admin_label="Will you recommend equipment purchases?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="Will you recommend equipment purchases?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>Only if the data supports it. Many capacity constraints can be addressed through process improvements, scheduling changes, workflow redesign, labor utilization improvements, or management system enhancements. The objective is to identify the most effective path to additional capacity—not automatically recommend capital expenditures.</p>[/et_pb_toggle][et_pb_toggle admin_label="What happens after the assessment?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="What happens after the assessment?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>You receive an Operational Capacity Assessment, Operational Assessment findings, capacity improvement opportunities, an executive findings presentation, and a Ramp-Up Plan. Some organizations use the findings internally. Others engage Alpha Nova to help implement the recommended improvements and accelerate results. The choice is entirely yours.</p>[/et_pb_toggle][et_pb_toggle admin_label="What kind of results can we expect?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="What kind of results can we expect?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>Every operation is different, but manufacturers commonly uncover opportunities to increase throughput, improve on-time delivery, reduce overtime, improve labor productivity, reduce lead times, and create additional capacity without adding significant overhead.</p>[/et_pb_toggle][et_pb_toggle admin_label="How do we know if this is right for us?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="How do we know if this is right for us?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|12px|0px|false|false"]<p>If your leadership team is asking questions such as “Can we handle more business?”, “Why are we constantly stretched despite adding resources?”, “Where should we invest to support growth?”, “What is limiting throughput?”, or “Are we truly at capacity?”, then the Capacity Constraint Assessment is likely a good fit. The assessment is built to answer those questions with data, analysis, and a practical path forward.</p>[/et_pb_toggle][et_pb_toggle admin_label="What if we are planning significant growth over the next 12–24 months?" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" title="What if we are planning significant growth over the next 12–24 months?" open="off" module_class="anca-faq-item" title_font="Arial|900|||||||" title_font_size="16px" title_line_height="1.5em" title_text_color="#070707" closed_title_text_color="#070707" icon_color="#d71920" closed_toggle_background_color="#ffffff" open_toggle_background_color="#ffffff" body_font="Arial||||||||" body_font_size="16px" body_line_height="1.55em" body_text_color="#6d6d6d" custom_padding="20px|24px|20px|24px|false|false" custom_margin="0px|0px|0px|0px|false|false"]<p>That is exactly when this assessment delivers the greatest value. Many manufacturers discover capacity limitations only after growth has already exposed them. By identifying constraints before they become critical, leadership can make informed decisions, reduce risk, and build a stronger foundation for sustainable growth. The best time to address a constraint is before it becomes the reason you miss a major opportunity.</p>[/et_pb_toggle][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section admin_label="14 | Request your assessment" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" fb_built="1" module_class="anca-section anca-form" background_color="#060606" custom_padding="76px|0px|90px|0px|false|false" custom_padding_phone="58px|0px|90px|0px|false|false" custom_padding_last_edited="on|phone" module_id="request-assessment"][et_pb_row admin_label="Request copy and form" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" column_structure="1_2,1_2" module_class="anca-row anca-stack-tablet" width="calc(100% - 40px)" max_width="1140px" use_custom_gutter="on" gutter_width="2" equalize_column_heights="off" custom_padding="0px|0px|0px|0px|false|false" custom_margin="0px|auto|0px|auto|false|false"][et_pb_column admin_label="Request assessment copy" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" type="1_2" module_class="" custom_padding="0px|0px|0px|0px|false|false"][et_pb_text admin_label="Request more information eyebrow" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|900||on|||||" text_text_color="#d71920" text_font_size="14px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|12px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" text_letter_spacing=".08em"]Request More Information[/et_pb_text][et_pb_text admin_label="Request assessment heading" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="#ffffff" text_font_size="16px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|18px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class="" header_2_font="Arial|900|||||||" header_2_text_color="#ffffff" header_2_font_size="54px" header_2_font_size_tablet="46px" header_2_font_size_phone="32px" header_2_font_size_last_edited="on|phone" header_2_line_height="1.08em" header_2_letter_spacing="-.04em"]<h2>Ready to Unlock Capacity for Your Next <span class="accent">Growth Stage?</span></h2>[/et_pb_text][et_pb_text admin_label="Request assessment introduction" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|400|||||||" text_text_color="rgba(255,255,255,.74)" text_font_size="17px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|22px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<p>Join dozens of manufacturers who have used the Capacity Constraint Assessment to identify constraints, unlock hidden capacity, and remove obstacles to growth.</p>[/et_pb_text][et_pb_text admin_label="Assessment benefits checklist" _builder_version="4.27.4" _module_preset="default" global_colors_info="{}" text_font="Arial|700|||||||" text_text_color="#ffffff" text_font_size="17px" text_line_height="1.55em" text_orientation="left" custom_margin="0px|0px|0px|0px|false|false" custom_padding="0px|0px|0px|0px|false|false" module_class=""]<ul class="check-list">
            <li>Identify what is limiting throughput</li>
            <li>Clarify whether your current system can support growth</li>
